package nl.streats1.cobbledollarsvillagersoverhaul.mixin;import org.objectweb.asm.tree.ClassNode;import org.spongepowered.asm.mixin.extensibility.IMixinConfigPlugin;import org.spongepowered.asm.mixin.extensibility.IMixinInfo;import java.util.ArrayList;import java.util.List;import java.util.Set;public final class CobbledollarsMixinPlugin implements IMixinConfigPlugin {    private static final String MCA_MOD_ID = "mca";    private static final String MCA_TRADE_PACKET = "net.conczin.mca.network.c2s.InteractionVillagerMessage";    private static final String MCA_VILLAGER = "net.conczin.mca.entity.VillagerEntityMCA";    @Override    public void onLoad(String mixinPackage) {    }    @Override    public String getRefMapperConfig() {        return null;    }    @Override    public boolean shouldApplyMixin(String targetClassName, String mixinClassName) {        if ("McaInteractionTradePacketMixin".equals(mixinClassName)) {            return isMcaLoaded();        }        if ("McaVillagerBeginTradeMixin".equals(mixinClassName)) {            return isMcaLoaded();        }        return true;    }    @Override    public void acceptTargets(Set<String> myTargets, Set<String> otherTargets) {    }    @Override    public List<String> getMixins() {        List<String> optional = new ArrayList<>();        if (isMcaLoaded()) {            optional.add("McaInteractionTradePacketMixin");            optional.add("McaVillagerBeginTradeMixin");        }        return optional;    }    @Override    public void preApply(String targetClassName, ClassNode targetClass, String mixinClassName, IMixinInfo mixinInfo) {    }    @Override    public void postApply(String targetClassName, ClassNode targetClass, String mixinClassName, IMixinInfo mixinInfo) {    }    /**     * MCA classes live in another mod JAR — {@link Class#forName} on our classloader often fails at runtime even when     * <p>     * MCA is installed. Prefer loader mod-list detection.     */    private static boolean isMcaLoaded() {        try {            Class<?> fabricLoaderClass = Class.forName("net.fabricmc.loader.api.FabricLoader");            Object loader = fabricLoaderClass.getMethod("getInstance").invoke(null);            Object loaded = fabricLoaderClass.getMethod("isModLoaded", String.class).invoke(loader, MCA_MOD_ID);            if (loaded instanceof Boolean b && b) {                return true;            }        } catch (Throwable ignored) {        }        return isClassPresent(MCA_VILLAGER) || isClassPresent(MCA_TRADE_PACKET);    }    private static boolean isClassPresent(String className) {        try {            Class.forName(className, false, CobbledollarsMixinPlugin.class.getClassLoader());            return true;        } catch (ClassNotFoundException e) {            return false;        }    }}